/**
 * OneTeam behaviour spec for the "generated by Captain" details popover
 * on messages.
 *
 * The message context, store and account features are faked. Covers
 * when the sparkle shows, prefetching the agent session, loading and
 * empty states, the step timeline (tools with arguments, handoffs by
 * scenario title or humanised agent name), knowledge sources,
 * reasoning, model and credit details, and layout classes.
 */
import { ref } from 'vue';
import { mount, flushPromises } from '@vue/test-utils';
import Details from '../CaptainGenerationDetails.vue';

const env = vi.hoisted(() => ({}));

vi.mock('../provider.js', () => ({
  useMessageContext: () => env.context,
}));
vi.mock('dashboard/composables/store', () => ({
  useStore: () => env.store,
  useMapGetter: () => env.user,
}));
vi.mock('dashboard/composables/useAccount', () => ({
  useAccount: () => ({ isCloudFeatureEnabled: () => env.captain }),
}));

const Popover = {
  name: 'Popover',
  props: ['align'],
  emits: ['show', 'hide'],
  template:
    '<div class="popover"><slot /><div class="content"><slot name="content" /></div></div>',
};

const mountDetails = async (slots = {}) => {
  const wrapper = mount(Details, {
    props: { messageId: 8 },
    slots,
    global: {
      stubs: {
        Popover,
        I18nT: {
          props: ['keypath'],
          template: '<span>{{ keypath }} <slot name="name" /></span>',
        },
        Icon: { props: ['icon'], template: '<i :class="icon" />' },
      },
      directives: { tooltip: {} },
    },
  });
  await flushPromises();
  return wrapper;
};

const content = wrapper => wrapper.find('.content');

describe('CaptainGenerationDetails behaviour', () => {
  beforeEach(() => {
    env.captain = true;
    env.user = ref({ type: 'User' });
    env.session = null;
    env.fetched = true;
    env.fetching = false;
    env.context = {
      orientation: ref('left'),
      variant: ref('agent'),
      createdAt: ref(1700000000),
    };
    env.store = {
      dispatch: vi.fn(),
      getters: {
        'captainAgentSessions/getSessionByMessageId': () => env.session,
        'captainAgentSessions/hasFetched': () => env.fetched,
        'captainAgentSessions/isFetching': () => env.fetching,
      },
    };
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('hides the sparkle without Captain and aligns to the message', async () => {
    env.captain = false;
    let wrapper = await mountDetails({
      default: '<b>body</b>',
      meta: '<i>meta</i>',
    });
    expect(wrapper.find('.popover').exists()).toBe(false);
    expect(wrapper.classes()).toContain('justify-start');
    expect(wrapper.find('b').element.parentElement.classList).not.toContain(
      'me-auto'
    );
    expect(wrapper.text()).toContain('meta');
    env.context.orientation.value = 'right';
    wrapper = await mountDetails();
    expect(wrapper.classes()).toContain('justify-end');
    expect(wrapper.find('.min-w-0.flex.items-center').exists()).toBe(false);
  });

  it('prefetches the session on hover, focus and open', async () => {
    const wrapper = await mountDetails({ default: '<b>body</b>' });
    expect(wrapper.classes()).toContain('justify-between');
    expect(wrapper.findComponent(Popover).props('align')).toBe('start');
    const button = wrapper.find('button');
    expect(button.classes()).toContain('text-n-slate-11/60');
    await button.trigger('mouseenter');
    await button.trigger('focus');
    expect(env.store.dispatch).toHaveBeenCalledWith(
      'captainAgentSessions/fetch',
      {
        messageId: 8,
        createdAt: 1700000000,
      }
    );
    wrapper.findComponent(Popover).vm.$emit('show');
    await flushPromises();
    expect(env.store.dispatch).toHaveBeenCalledTimes(3);
    expect(button.classes()).toContain('text-n-slate-12');
    wrapper.findComponent(Popover).vm.$emit('hide');
    await flushPromises();
    expect(button.classes()).toContain('text-n-slate-11/60');
  });

  it('uses amber on private notes and aligns the popover to the end', async () => {
    env.context.variant.value = 'private';
    env.context.orientation.value = 'right';
    const wrapper = await mountDetails();
    expect(wrapper.findComponent(Popover).props('align')).toBe('end');
    expect(wrapper.find('button').classes()).toContain('text-n-amber-12/40');
    wrapper.findComponent(Popover).vm.$emit('show');
    await flushPromises();
    expect(wrapper.find('button').classes()).toContain('text-n-amber-12/80');
  });

  it('shows loading and empty states', async () => {
    env.fetched = false;
    let wrapper = await mountDetails();
    expect(content(wrapper).text()).toBe(
      'CONVERSATION.CAPTAIN_GENERATION.LOADING'
    );
    env.fetched = true;
    env.fetching = true;
    wrapper = await mountDetails();
    expect(content(wrapper).text()).toBe(
      'CONVERSATION.CAPTAIN_GENERATION.LOADING'
    );
    env.fetching = false;
    wrapper = await mountDetails();
    expect(content(wrapper).text()).toBe(
      'CONVERSATION.CAPTAIN_GENERATION.EMPTY'
    );
  });

  it('builds the timeline, sources and reasoning from the run', async () => {
    env.session = {
      llmModel: 'gpt-x',
      creditsConsumed: 2,
      scenarios: [{ id: 5, title: 'Refunds' }],
      citations: [
        { id: 1, title: 'Guide', link: 'https://docs/guide' },
        { id: 2, link: 'https://docs/raw' },
      ],
      usedFaqs: [{ id: 3, title: 'How to pay' }],
      runContext: [
        null,
        { role: 'user', content: 'hi' },
        {
          role: 'assistant',
          agentName: 'chatwoot_assistant',
          toolCalls: [
            {
              name: 'captain--tools--faq_lookup',
              arguments: { query: 'pay', labelName: 'vip' },
            },
            { name: 'handoff_to_scenario_5' },
            { name: 'custom_get_order', arguments: null },
            {},
          ],
        },
        { role: 'assistant', agentName: 'chatwoot_assistant' },
        {
          role: 'assistant',
          agentName: 'scenario_5_refund_agent',
          content: { reasoning: 'Old' },
        },
        { role: 'assistant', agentName: 'scenario_9_chatwoot_uptime_agent' },
        { role: 'assistant', content: { reasoning: 'Customer asked to pay' } },
      ],
    };
    const wrapper = await mountDetails();
    const text = content(wrapper).text();
    expect(text).toContain('CONVERSATION.CAPTAIN_GENERATION.TIMELINE');
    const steps = content(wrapper).findAll('.flex.gap-2\\.5');
    expect(steps).toHaveLength(5);
    expect(steps.map(s => s.find('i').classes()[0])).toEqual([
      'i-ph-wrench',
      'i-ph-wrench',
      'i-ph-wrench',
      'i-ph-user-switch',
      'i-ph-user-switch',
    ]);
    expect(steps[0].text()).toContain('Query: pay, Label Name: vip');
    expect(steps[1].text()).toContain(
      'Custom Get Order'.replace('Custom ', '')
    );
    expect(steps[1].text()).not.toContain(':');
    expect(steps.at(-1).classes()).not.toContain('pb-3');
    expect(
      content(wrapper)
        .findAll('a')
        .map(a => a.text())
    ).toEqual(['Guide', 'https://docs/raw']);
    expect(text).toContain('How to pay');
    expect(text).toContain('Customer asked to pay');
    // Model and credits show in development builds.
    expect(text).toContain('CONVERSATION.CAPTAIN_GENERATION.MODEL');
    expect(text).toContain('CONVERSATION.CAPTAIN_GENERATION.CREDITS');
  });

  it('names steps with i18n keys and humanised names', async () => {
    env.session = {
      runContext: [
        {
          role: 'assistant',
          agentName: 'a',
          toolCalls: [{ name: 'captain--tools--faq_lookup' }],
        },
        { role: 'assistant', agentName: 'scenario_5_refund_agent' },
        { role: 'assistant', agentName: 'scenario_9_chatwoot_uptime_agent' },
      ],
      scenarios: [{ id: 5, title: 'Refunds' }],
    };
    const wrapper = await mountDetails();
    const html = content(wrapper).html();
    expect(html).toContain('FAQ Lookup');
    expect(html).toContain('Refunds');
    expect(html).toContain('Chatwoot uptime');
  });

  it('humanises handoffs when the session lists no scenarios', async () => {
    env.session = {
      runContext: [
        { role: 'assistant', agentName: 'chatwoot_assistant' },
        { role: 'assistant', agentName: 'scenario_2_billing_agent' },
      ],
    };
    const wrapper = await mountDetails();
    expect(content(wrapper).text()).toContain('Billing');
  });

  it('shows only what the session has', async () => {
    env.session = { runContext: 'not-a-list' };
    const wrapper = await mountDetails();
    expect(content(wrapper).text()).not.toContain('TIMELINE');
    expect(content(wrapper).text()).not.toContain('SOURCES');
    expect(content(wrapper).text()).not.toContain('REASONING');
  });

  it('hides model details outside development unless super admin', async () => {
    vi.stubEnv('DEV', false);
    env.session = { runContext: [] };
    let wrapper = await mountDetails();
    expect(content(wrapper).text()).not.toContain('MODEL');
    env.user.value = { type: 'SuperAdmin' };
    wrapper = await mountDetails();
    expect(content(wrapper).text()).toContain('MODEL');
  });
});
